# ---------- 断言与写盘 ----------
assert set(P.keys()) == set(BATCH), f"id 集与本批不一致: {set(P.keys()) ^ set(BATCH)}"
assert len(P) == 20, f"写出数应为 20，实为 {len(P)}"
REQ = {"case_id", "prediction_text", "basis", "confidence", "trigger"}
TREQ = {"changed_main", "reserve_used", "disputed", "reason"}
for cid, v in P.items():
    rec = {"case_id": cid, **v}
    assert REQ <= set(rec.keys()), f"{cid} 字段缺失"
    assert TREQ <= set(rec["trigger"].keys()), f"{cid} trigger 字段缺失"
    assert isinstance(rec["confidence"], float) and 0.0 <= rec["confidence"] <= 1.0
    assert rec["basis"].splitlines()[0].startswith("六爻"), f"{cid} basis 首行未写体系"
    assert all(isinstance(rec["trigger"][k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    with open(os.path.join(OUT, f"{cid}.json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)

# 回读核对
written = sorted(fn[:-5] for fn in os.listdir(OUT) if fn.endswith(".json") and fn[:-5] in set(BATCH))
assert written == sorted(BATCH), f"回读不一致: {written}"
cm = sum(1 for v in P.values() if v["trigger"]["changed_main"])
ru = sum(1 for v in P.values() if v["trigger"]["reserve_used"])
di = sum(1 for v in P.values() if v["trigger"]["disputed"])
print(f"OK 本批={len(BATCH)} 已写={len(written)}")
print(f"trigger changed_main={cm} reserve_used={ru} disputed={di}")
print("ids:", ",".join(sorted(BATCH)))
